// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BiConsumer;

/**
 * Per-store hierarchical Gaussian posteriors over log runtime. The additive model is Y = G(regime-global) + F(family
 * shape) + V(exact variant) + noise, so a new variant in a well-measured family starts from the family's evidence
 * instead of from nothing, and pairwise comparisons between arms can cancel the hierarchy components they share. Two
 * lanes keep feature-priced and directly-timed evidence apart: {@link Lane#RESIDUAL} models log T minus the feature
 * model's log prediction, {@link Lane#DIRECT} models log T itself (the lane for strategies whose features the machine
 * model cannot price). Every map is keyed by {@link LmdbNativeRegimeKey}, which makes regime isolation structural: an
 * observation taken while the adjacency view is building cannot touch the steady-state nodes.
 *
 * Reads are lock-free: a read decays a copy of each node (never writing back — the next update persists the decay) and
 * lazily applies epoch inflation to exact nodes. Updates replace whole immutable nodes via
 * {@link ConcurrentHashMap#compute}; the three-node update is not cross-node atomic, which is accepted — the Huber clip
 * and the per-level variance floors bound what a racing pair of updates can do, the same class of race the previous
 * EWMA store carried.
 */
final class LmdbNativeCostPosteriorStore {

	/** Which quantity the posterior describes. */
	enum Lane {
		/** log T − log T̂_features: the residual against the machine feature model. */
		RESIDUAL,
		/** log T directly; the lane for arms without comparable feature estimates. */
		DIRECT
	}

	enum Level {
		GLOBAL,
		FAMILY,
		EXACT
	}

	/** Exact variants admitted per (regime, lane) sub-population; mirrors the previous store-model cap. */
	static final int MAX_VARIANTS_PER_SUBPOPULATION = 4_096;

	private static final double NOISE_BETA = 1.0 / 32.0;
	private static final double MINIMUM_CENSOR_WEIGHT = 0.1;

	record GlobalKey(LmdbNativeRegimeKey regime, Lane lane) {
	}

	record FamilyKey(LmdbNativeRegimeKey regime, Lane lane, LmdbNativeFamilyShapeKey shape) {
	}

	record SubPopulationKey(LmdbNativeRegimeKey regime, Lane lane) {
	}

	record ExactKey(LmdbNativeRegimeKey regime, Lane lane, LmdbNativePhysicalVariantKey variant) {

		/**
		 * The exact posterior key quantizes the variant's consumption-fraction bucket to deciles: the raw 0-100 bucket
		 * multiplies the variant population by regime and lane, and its volatility is a known source of orphaned
		 * evidence.
		 */
		static ExactKey of(LmdbNativeRegimeKey regime, Lane lane, LmdbNativePhysicalVariantKey variant) {
			int bucket = variant.consumptionFractionBucket();
			int decile = bucket / 10 * 10;
			LmdbNativePhysicalVariantKey quantized = bucket == decile ? variant
					: variant.toBuilder().consumptionFractionBucket(decile).build();
			return new ExactKey(regime, lane, quantized);
		}

		FamilyKey familyKey() {
			return new FamilyKey(regime, lane, LmdbNativeFamilyShapeKey.of(variant));
		}

		GlobalKey globalKey() {
			return new GlobalKey(regime, lane);
		}

		SubPopulationKey subPopulation() {
			return new SubPopulationKey(regime, lane);
		}
	}

	/** The decayed three-node view a prediction is built from; absent levels are represented by their priors. */
	record Reading(LmdbNativePosteriorNode global, LmdbNativePosteriorNode family, LmdbNativePosteriorNode exact,
			boolean globalPresent, boolean familyPresent, boolean exactPresent) {

		double meanLog() {
			return global.meanLog + family.meanLog + exact.meanLog;
		}

		double epistemicVariance() {
			return global.epistemicVariance + family.epistemicVariance + exact.epistemicVariance;
		}

		double noiseVariance() {
			return exact.noiseVariance;
		}

		double nEff() {
			return exact.nEff();
		}

		boolean anyEvidence() {
			return globalPresent || familyPresent || exactPresent;
		}
	}

	private final LmdbNativePosteriorConfig config;
	private final ConcurrentHashMap<GlobalKey, LmdbNativePosteriorNode> global = new ConcurrentHashMap<>();
	private final ConcurrentHashMap<FamilyKey, LmdbNativePosteriorNode> families = new ConcurrentHashMap<>();
	private final ConcurrentHashMap<ExactKey, LmdbNativePosteriorNode> variants = new ConcurrentHashMap<>();
	private final ConcurrentHashMap<SubPopulationKey, AtomicInteger> variantAdmissions = new ConcurrentHashMap<>();

	LmdbNativeCostPosteriorStore(LmdbNativePosteriorConfig config) {
		this.config = Objects.requireNonNull(config, "config");
	}

	LmdbNativePosteriorConfig config() {
		return config;
	}

	Reading read(ExactKey key, long epoch, long nowMillis) {
		LmdbNativePosteriorNode g = global.get(key.globalKey());
		LmdbNativePosteriorNode f = families.get(key.familyKey());
		LmdbNativePosteriorNode v = variants.get(key);
		boolean globalPresent = g != null && g.observationCount() > 0;
		boolean familyPresent = f != null && f.observationCount() > 0;
		boolean exactPresent = v != null && v.observationCount() > 0;
		return new Reading(
				decayedOrPrior(g, Level.GLOBAL, epoch, nowMillis),
				decayedOrPrior(f, Level.FAMILY, epoch, nowMillis),
				inflateForEpoch(decayedOrPrior(v, Level.EXACT, epoch, nowMillis), epoch),
				globalPresent, familyPresent, exactPresent);
	}

	/**
	 * A fully observed value {@code y} in the lane's log units. Returns the clipped standardized innovation, which the
	 * caller feeds to the change detector. {@code weight} is 1.0 for a complete run, or the consumed fraction (floored
	 * at 0.25) for a LIMIT-truncated but still eligible run.
	 */
	double updateCompleted(ExactKey key, double y, double weight, long epoch, long nowMillis) {
		Reading reading = read(key, epoch, nowMillis);
		double mean = reading.meanLog();
		double epistemic = reading.epistemicVariance();
		double noise = reading.noiseVariance();
		double totalVariance = epistemic + noise;
		double sigma = Math.sqrt(totalVariance);
		double standardized = (y - mean) / sigma;
		double clipped = LmdbNativeGaussianMath.huberClip(standardized, config.huberSigmas());
		double innovation = clipped * sigma;

		double w = Math.max(0.25, Math.min(1.0, weight));
		if (reading.exact().completedCount == 0L) {
			// First completion of this exact variant: initialize instead of filtering. The Huber clip protects an
			// established posterior from one outlier; with no completed evidence there is nothing to protect, and
			// clip-limited walking from the prior mean (log 1ns in the DIRECT lane) left arms priced orders of
			// magnitude low for their first ~15 runs — long enough for nEff to cross the cold-start rescue floor
			// with a garbage price (HC:8 2026-08-22 arbitration lock-in). Deadline censors, which only establish a
			// lower bound, must not block the seeding either. The raw innovation is distributed by noise-free
			// Kalman gains (they sum to one, so the hierarchy lands exactly on the observed value, and an
			// established level's small variance keeps its share small automatically). One sample says nothing
			// about run-to-run scatter, so the noise EWMA is not fed, and the change detector sees no drift signal
			// from an initialization.
			double rawInnovation = y - mean;
			global.put(key.globalKey(), gainUpdate(reading.global(), epistemic, rawInnovation,
					config.varianceFloorGlobal(), reading.global().noiseVariance, w, true, epoch, nowMillis));
			families.put(key.familyKey(), gainUpdate(reading.family(), epistemic, rawInnovation,
					config.varianceFloorFamily(), reading.family().noiseVariance, w, true, epoch, nowMillis));
			storeExact(key, gainUpdate(reading.exact(), epistemic, rawInnovation, config.varianceFloorExact(),
					reading.exact().noiseVariance, w, true, epoch, nowMillis));
			return 0.0;
		}
		double newNoise = Math.max(config.noiseFloorLog(),
				(1.0 - NOISE_BETA) * noise + NOISE_BETA * Math.max(0.0, innovation * innovation - epistemic));

		global.put(key.globalKey(), gainUpdate(reading.global(), totalVariance, innovation,
				config.varianceFloorGlobal(), reading.global().noiseVariance, w, true, epoch, nowMillis));
		families.put(key.familyKey(), gainUpdate(reading.family(), totalVariance, innovation,
				config.varianceFloorFamily(), reading.family().noiseVariance, w, true, epoch, nowMillis));
		storeExact(key, gainUpdate(reading.exact(), totalVariance, innovation, config.varianceFloorExact(), newNoise,
				w, true, epoch, nowMillis));
		return clipped;
	}

	/**
	 * A right-censored observation: the run was cancelled at the deadline, so all we know is Y &gt;
	 * {@code logDeadline}. Assumed-density filtering against the truncated Gaussian: mean shift sigma*lambda(a),
	 * variance retention delta = lambda(lambda - a) in (0,1). The mean-shift lambda is Huber-bounded so one
	 * pathological censoring far above the current mean cannot swing the posterior; the true delta still sets the
	 * evidence weight, clamped to [0.1, 1.0]. Intrinsic noise is deliberately untouched — a censoring says nothing
	 * about within-arm dispersion.
	 */
	void updateCensored(ExactKey key, double logDeadline, long epoch, long nowMillis) {
		Reading reading = read(key, epoch, nowMillis);
		double mean = reading.meanLog();
		double epistemic = reading.epistemicVariance();
		double noise = reading.noiseVariance();
		double totalVariance = epistemic + noise;
		double sigma = Math.sqrt(totalVariance);
		double a = (logDeadline - mean) / sigma;
		double lambda = LmdbNativeGaussianMath.millsRatioUpper(a);
		double delta = Math.max(0.0, Math.min(1.0, lambda * (lambda - a)));
		double boundedLambda = Math.min(lambda, config.huberSigmas() + Math.max(a, 0.0));
		double meanShift = sigma * boundedLambda;
		double w = Math.max(MINIMUM_CENSOR_WEIGHT, Math.min(1.0, delta));

		global.put(key.globalKey(), censorUpdate(reading.global(), totalVariance, meanShift, delta,
				config.varianceFloorGlobal(), w, epoch, nowMillis));
		families.put(key.familyKey(), censorUpdate(reading.family(), totalVariance, meanShift, delta,
				config.varianceFloorFamily(), w, epoch, nowMillis));
		storeExact(key, censorUpdate(reading.exact(), totalVariance, meanShift, delta, config.varianceFloorExact(), w,
				epoch, nowMillis));
	}

	int admittedVariants(SubPopulationKey subPopulation) {
		AtomicInteger count = variantAdmissions.get(subPopulation);
		return count == null ? 0 : count.get();
	}

	void forEachGlobal(BiConsumer<GlobalKey, LmdbNativePosteriorNode> consumer) {
		global.forEach(consumer);
	}

	void forEachFamily(BiConsumer<FamilyKey, LmdbNativePosteriorNode> consumer) {
		families.forEach(consumer);
	}

	void forEachExact(BiConsumer<ExactKey, LmdbNativePosteriorNode> consumer) {
		variants.forEach(consumer);
	}

	/** Persistence restore path: install a loaded node without running an observation update. */
	void restoreGlobal(GlobalKey key, LmdbNativePosteriorNode node) {
		global.put(key, node);
	}

	void restoreFamily(FamilyKey key, LmdbNativePosteriorNode node) {
		families.put(key, node);
	}

	void restoreExact(ExactKey key, LmdbNativePosteriorNode node) {
		if (admit(key)) {
			variants.put(key, node);
		}
	}

	private LmdbNativePosteriorNode decayedOrPrior(LmdbNativePosteriorNode node, Level level, long epoch,
			long nowMillis) {
		if (node == null) {
			return LmdbNativePosteriorNode.prior(config.priorVariance(level), config.noiseInitialLog(), epoch,
					nowMillis);
		}
		return node.decayed(nowMillis, config.decayHalfLifeMillis(), config.priorVariance(level));
	}

	private LmdbNativePosteriorNode inflateForEpoch(LmdbNativePosteriorNode exact, long epoch) {
		if (exact.epoch >= epoch) {
			return exact;
		}
		double inflated = Math.max(exact.epistemicVariance * 4.0, config.varianceFloorExact() * 8.0);
		return exact.withEpoch(epoch, Math.min(inflated, config.priorVarianceExact()));
	}

	private LmdbNativePosteriorNode gainUpdate(LmdbNativePosteriorNode node, double totalVariance, double innovation,
			double floor, double newNoise, double weight, boolean completed, long epoch, long nowMillis) {
		double v = node.epistemicVariance;
		double gain = v / totalVariance;
		double newMean = node.meanLog + gain * innovation;
		double newVariance = Math.max(floor, v - v * v / totalVariance);
		return new LmdbNativePosteriorNode(newMean, newVariance, newNoise, node.weightSum + weight,
				node.squaredWeightSum + weight * weight,
				completed ? node.completedCount + 1 : node.completedCount,
				completed ? node.censoredCount : node.censoredCount + 1,
				epoch, nowMillis);
	}

	private LmdbNativePosteriorNode censorUpdate(LmdbNativePosteriorNode node, double totalVariance, double meanShift,
			double delta, double floor, double weight, long epoch, long nowMillis) {
		double v = node.epistemicVariance;
		double gain = v / totalVariance;
		double newMean = node.meanLog + gain * meanShift;
		double newVariance = Math.max(floor, v * (1.0 - gain * delta));
		return new LmdbNativePosteriorNode(newMean, newVariance, node.noiseVariance, node.weightSum + weight,
				node.squaredWeightSum + weight * weight, node.completedCount, node.censoredCount + 1, epoch, nowMillis);
	}

	private void storeExact(ExactKey key, LmdbNativePosteriorNode updated) {
		if (variants.containsKey(key) || admit(key)) {
			variants.put(key, updated);
		}
	}

	private boolean admit(ExactKey key) {
		AtomicInteger count = variantAdmissions.computeIfAbsent(key.subPopulation(), ignored -> new AtomicInteger());
		while (true) {
			int current = count.get();
			if (current >= MAX_VARIANTS_PER_SUBPOPULATION) {
				return false;
			}
			if (count.compareAndSet(current, current + 1)) {
				return true;
			}
		}
	}
}
